using namespace std;

///MAX FLOW
struct Edge{
    int u;
    int v;
    int c;
    int r;
    Edge( int uu, int vv, int cc, int rr): u(uu), v(vv), c(cc), r(rr){}
};

vector< Edge > E;
vector< vector<int> > ady; //posee indices de aristas

int maxflow( int source , int sink ){

    for( int f = 0; ;){
        vector<int> prev( ady.size() , -1 );
        queue<int> Q;
        Q.push( source );

        while( !Q.empty() ){
            int u = Q.front(); Q.pop();
            for( int i = 0 ; i < ady[ u ].size(); ++i ){
                 int e = ady[ u ][ i ];
                 int v = E[ e ].v;
                 if( E[ e ].c == 0 || prev[ v ] >= 0 )continue;
                 Q.push( v );
                 prev[ v ] = e;
            }
        }

        if( prev[ sink ] < 0 )return f;
        int c = 0x7fffffff;
        for( int x = sink ; x != source ; x = E[ prev[ x ] ].u ){
            c <?= E[ prev[ x ] ].c;
        }
        for( int x = sink ; x != source ; x = E[ prev[ x ] ].u ){
            E[ prev[ x ] ].c -= c;
            E[ E[ prev[ x ] ].r ].c += c;
        }
        f += c;

    }

}

void add( int u , int v , int c , bool dirigido = true ){
    //cout<<u<<" -> "<<v<<" capacidad "<<c<<endl;
    Edge e1( u , v , c , E.size() + 1 );
    ady[ u ].push_back( E.size() );
    E.push_back( e1 );
    ///capadidad 0 si es dirigido
    Edge e2( v , u , ( dirigido )? 0 : c , E.size() - 1 );
    ady[ v ].push_back( E.size() );
    E.push_back( e2 );
}
///END MAX FLOW







#define MAX 11
int xini , yini, t , n;
char S[ MAX ][ MAX ][ 65 ], R[ MAX ][ MAX ];
int dx[ 4 ] = { 1 , -1 , 0 ,  0 };
int dy[ 4 ] = { 0 ,  0 , 1 , -1 };
///avance de reactor Z
void AvanceZ( ){
    int nx , ny;
    for( int i = 0 ; i < t ; ++i ){
        for( int x = 0 ; x < n ; ++x )
            for( int y = 0 ; y < n ; ++y )
                S[ x ][ y ][ i + 1 ] = S[ x ][ y ][ i ];
        for( int x = 0 ; x < n ; ++x ){
            for( int y = 0 ; y < n ; ++y ){
                if( S[ x ][ y ][ i ] == 'Z' ){
                    for( int k = 0 ; k < 4 ; ++k ){
                        nx = dx[ k ] + x;
                        ny = dy[ k ] + y;
                        if( nx >= 0 && ny >= 0 && nx < n && ny < n && S[ nx ][ ny ][ i ] != 'Y'){
                            S[ nx ][ ny ][ i + 1 ] = 'Z';
                        }
                    }
                }
            }
        }
    }
}

void Ver(){
    cout<<endl;
    for( int i = 0 ; i <= t ; ++i ){
        cout<<"Tiempo "<<i<<endl;
        for( int x = 0 ; x < n ; ++x ){
            for( int y = 0 ; y < n ; ++y ){
                 cout<<S[ x ][ y ][ i ];
            }
            cout<<endl;
        }
        cout<<endl;
    }
}

//int d[ MAX ][ MAX ][ 65 ];

struct Estado{
    int x , y , d, val;
    Estado( int xx , int yy , int dd ): x( xx ) , y( yy ) , d( dd ){}
    //Estado( int xx , int yy , int dd , int v ): x( xx ) , y( yy ) , d( dd ) , val( v ){}
};
bool seen[ MAX ][ MAX ][ 65 ];

int getId( int x , int y , int col ){ return x * col + y;}
int in( int u ){ return u  + n * n ;}
int out( int u ){ return u;}
//int in( int u ){ return 2 * u + n * n ;}
//int out( int u ){ return 2 * u;}

void bfs( int x , int y ){
    memset( seen , 0 , sizeof( seen ) );
    queue<Estado> Q;
    Q.push( Estado( x , y , 0 ) );
    int nx , ny;
    seen[ x ][ y ][ 0 ] = true;
    while( !Q.empty() ){
        Estado act = Q.front(); Q.pop();
        if( act.d > t )continue;
        if( R[ act.x ][ act.y ] > '0' && R[ act.x ][ act.y ] <= '9' ){
            add( getId( x , y , n ) , in( getId( act.x , act.y , n ) ) , S[ x ][ y ][ 0 ]- '0' , false );
            //return;
        }
        //seen[ act.x ][ act.y ] = true;
        if( S[ act.x ][ act.y ][ act.d ] == 'Z' )continue;
        for( int i = 0 ; i < 4 ; ++i ){
            nx = dx[ i ] + act.x;
            ny = dy[ i ] + act.y;
            if( nx>= 0 && ny >= 0 && nx < n && ny < n && S[ nx ][ ny ][ act.d ] != 'Y' && S[ nx ][ ny ][ act.d ] != 'Z' && !seen[ nx ][ ny ][ act.d ] ){
            //if( nx >= 0 && ny >= 0 && nx < n && ny < n && R[ nx ][ ny ] != 'Y' && R[ nx ][ ny ] != 'Z' && !seen[ nx ][ ny ] ){
                seen[ nx ][ ny ][ act.d ] = true;
                Q.push( Estado( nx , ny , act.d + 1 ) );
            }
        }
    }
}



int main(){


    char c;
    scanf("%d %d" , &n , &t );

    for( int i = 0 ; i < n ; ++i ){
        for( int j = 0 ; j < n ; ++j ){
            scanf(" %c" , &S[ i ][ j ][ 0 ] );
        }
    }
    AvanceZ();
    //Ver();
    int source = 2 * n * n + n * n , sink = 2 * n * n + n * n + 1;
    E.clear();
    ady = vector< vector<int> >( 5 * n * n , vector<int> () );
    for( int i = 0 ; i < n ; ++i ){
        for( int j = 0 ; j < n ; ++j ){
            scanf(" %c" , &R[ i ][ j ] );
            if( '0' < R[ i ][ j ] && R[ i ][ j ] <= '9' ){
                //add( in( getId( i , j , n ) ) , sink , R[ i ][ j ] - '0' , false );
                add( in( getId( i , j , n ) ) , in( in( getId( i , j , n ) ) ) , R[ i ][ j ] - '0' , false );
                //add( out( getId( i , j , n ) ) , in( getId( i , j , n ) ), R[ i ][ j ] - '0' , false );
                //add( in( getId( i , j , n ) ) , sink , 1<<30 , false );
                add( in( in( getId( i , j , n ) ) ) , sink , 1<<30 , false );
            }
        }
    }


    ///shortest path

    for( int i = 0 ; i < n ; ++i ){
        for( int j = 0 ; j < n ; ++j ){
            if( '0' < S[ i ][ j ][ 0 ] && S[ i ][ j ][ 0 ] <= '9' ){
                bfs( i , j );
                add( source , getId( i , j , n ) , S[ i ][ j ][ 0 ] - '0' , false );
                //add( source , getId( i , j , n ) , 1<<30 , false );
            }
        }
    }

    printf("%d\n" , maxflow( source , sink ) );
    return 0;
}

